/*** Added to show tooltip info for attachment-related list - START ***/
.att-tooltip {
    display: inline-block;
    cursor: pointer;
    text-align: center;
  }
  .att-tooltip .att-tooltiptext {
    visibility: hidden;
    width: 230px;
    max-width: 300px; /* Adjust the maximum width as needed */
    background: #16325C;
    color: white;
    text-align: center;
    border-radius: 6px;
    padding: 6px;
    position: absolute;
    z-index: 1;
    font-size: 13px!important;
    opacity: 0;
    transition: opacity 0.3s;
    top: -7%;
    left: 10%;
    font-family:Roboto;
  }
  .att-tooltip .att-tooltiptext::after {
      content: '';
      position: absolute;
      width: 12px;
      height: 12px;
      left: 33%;
      transform: translate(-50%,-50%) rotate(45deg);
      background-color: #16325C;
      top: 26px;
  }
  .att-tooltip:hover .att-tooltiptext {
    visibility: visible;
    opacity: 1;
  }
/*** Added to show tooltip info for attachment-related list - END ***/


